def _serialize_calibration_value(value):
    """Serialize a single calibration statistic into a JSON-friendly structure.

    numpy arrays and numpy scalars keep enough information (dtype and shape) to be restored
    faithfully. Plain python values (including bin counts already stored as ``int``) are passed
    through untouched.
    """
    if isinstance(value, np.ndarray):
        return {
            "__type__": "ndarray",
            "dtype": str(value.dtype),
            "shape": list(value.shape),
            "values": value.tolist(),
        }
    if isinstance(value, np.generic):
        return {
            "__type__": "npscalar",
            "dtype": str(value.dtype),
            "value": value.item(),
        }
    return value


def _deserialize_calibration_value(value):
    """Inverse of :func:`_serialize_calibration_value`."""
    if isinstance(value, dict) and "__type__" in value:
        kind = value["__type__"]
        if kind == "ndarray":
            arr = np.array(value["values"], dtype=value["dtype"])
            return arr.reshape(tuple(value["shape"]))
        if kind == "npscalar":
            return np.dtype(value["dtype"]).type(value["value"])
    return value


def save_tensors_data(tensors_data: "TensorsData", path, smooth_quant: bool = False) -> None:
    """Serialize a :class:`TensorsData` object to a JSON file.

    Missing parent directories are created automatically. The resulting JSON includes a top-level
    ``smooth_quant`` boolean field. Scalar numpy bin values are written as plain integers.
    """
    path = Path(path)
    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)

    data = {}
    for key in tensors_data.keys():
        tensor = tensors_data[key]
        attrs = {}
        for attr in tensor._attrs:
            attr_value = getattr(tensor, attr)
            if attr == "bins":
                # Bin counts are always serialized as plain integers.
                attrs[attr] = int(attr_value)
            else:
                attrs[attr] = _serialize_calibration_value(attr_value)
        data[key] = attrs

    payload = {
        "CLS": "TensorsData",
        "smooth_quant": bool(smooth_quant),
        "calibration_method": tensors_data.calibration_method.name,
        "data": data,
    }

    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f)


def load_tensors_data(path) -> "TensorsData":
    """Deserialize a :class:`TensorsData` object from a JSON file.

    Raises :class:`FileNotFoundError` if the file does not exist. numpy arrays (including scalar
    arrays with shape ``()``) are restored with their original dtypes. A legacy cache without a
    ``smooth_quant`` field is treated as ``smooth_quant=False``.
    """
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f"Calibration cache file {str(path)!r} does not exist.")

    with open(path, encoding="utf-8") as f:
        payload = json.load(f)

    calibration_method = CalibrationMethod[payload["calibration_method"]]

    data = {}
    for key, attrs in payload["data"].items():
        kwargs = {attr: _deserialize_calibration_value(value) for attr, value in attrs.items()}
        data[key] = TensorData(**kwargs)

    tensors_data = TensorsData(calibration_method, data)
    tensors_data.smooth_quant = bool(payload.get("smooth_quant", False))
    return tensors_data
